WITH base AS (SELECT id, full_name, email, dept_id, manager_id, hire_date, is_remote, SPLIT(LOWER(email), '@')[0] AS email_user FROM employees WHERE hire_date >= DATE '2023-03-20') SELECT manager_id, DATE_TRUNC('WEEK', hire_date) AS week_start, COUNT(DISTINCT manager_id) AS distinct_manager_ids, COUNT(*) AS event_count, GROUPING_ID() AS grouping_level FROM base GROUP BY GROUPING SETS ((manager_id, DATE_TRUNC('WEEK', hire_date)), (manager_id)) ORDER BY distinct_manager_ids DESC;
